<template>
  <div class="publish-container">
    <!-- 紧急程度选择 -->
    <div class="urgency-section">
      <div 
        class="urgency-btn urgent" 
        :class="{ active: isUrgent }" 
        @click="setUrgency(true)"
      >
        重要紧急任务
      </div>
      <div 
        class="urgency-btn normal" 
        :class="{ active: !isUrgent }" 
        @click="setUrgency(false)"
      >
        不紧急任务
      </div>
    </div>

    <!-- 任务信息 -->
    <div class="task-section">
      <label>任务名称</label>
      <input 
        v-model="taskName" 
        placeholder="请输入任务名称" 
        class="task-name-input"
      />
	<!-- 人员姓名与时长 -->
          <div class="process-field">
            <label>人员姓名</label>
            <input 
              v-model="process.person" 
              placeholder="请输入人员姓名" 
              class="process-input"
            />
          </div>
		  <div class="process-field">
		    <label>时长(小时)</label>
		    <input 
		      v-model.number="process.duration" 
		      type="number" 
		      min="0.5" 
		      step="0.5" 
		      placeholder="请输入时长" 
		      class="process-input"
		    />
		  </div>
      <!-- 工序列表 -->
      <div class="process-list">
        <div class="process-header">
          <span>工序</span>
          <button @click="addProcess" class="add-btn">+ 新增工序</button>
        </div>
        
        <div 
          v-for="(process, index) in processes" 
          :key="index" 
          class="process-item"
        >
          <div class="process-field">
            <label>人员姓名</label>
            <input 
              v-model="process.person" 
              placeholder="请输入人员姓名" 
              class="process-input"
            />
          </div>
          <div class="process-field">
            <label>时长(小时)</label>
            <input 
              v-model.number="process.duration" 
              type="number" 
              min="0.5" 
              step="0.5" 
              placeholder="请输入时长" 
              class="process-input"
            />
          </div>
          <button 
            v-if="processes.length > 1" 
            @click="removeProcess(index)" 
            class="remove-btn"
          >
            ×
          </button>
        </div>
      </div>
      
      <!-- 发布按钮 -->
      <button 
        @click="publishTask" 
        :disabled="!canPublish" 
        class="publish-btn"
        :class="{ disabled: !canPublish }"
      >
        {{ canPublish ? '发布任务' : '请完善任务信息' }}
      </button>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      isUrgent: true, // 默认重要紧急
      taskName: '',
      processes: [
        { person: '', duration: null }
      ]
    }
  },
  computed: {
    // 验证是否可发布
    canPublish() {
      if (!this.taskName.trim()) return false
      if (this.processes.length === 0) return false
      
      return this.processes.every(proc => 
        proc.person.trim() && 
        proc.duration > 0
      )
    }
  },
  methods: {
    setUrgency(value) {
      this.isUrgent = value
    },
    addProcess() {
      this.processes.push({ person: '', duration: null })
    },
    removeProcess(index) {
      if (this.processes.length > 1) {
        this.processes.splice(index, 1)
      }
    },
    publishTask() {
      if (!this.canPublish) return
      
      // 实际项目中这里调用API提交数据
      const taskData = {
        urgency: this.isUrgent ? 'urgent' : 'normal',
        taskName: this.taskName.trim(),
        processes: this.processes.map(p => ({
          person: p.person.trim(),
          duration: p.duration
        }))
      }
      
      console.log('发布任务:', taskData)
      alert('任务发布成功！')
      
      // 重置表单（实际项目中根据需求决定）
      // this.taskName = ''
      // this.processes = [{ person: '', duration: null }]
      // this.isUrgent = true
    }
  }
}
</script>

